using System;
using System.Collections.Generic;
using UnityEngine;

namespace MonsterTactics
{
    /// <summary>
    /// U6.10.3 animation clips generated by the optional Editor importer.
    /// Holds genuine downloaded GIF frames, not synthesized frames.
    /// Kept in Resources to work for shop purchases, bench units, AI and evolutions.
    /// </summary>
    public sealed class MonsterTacticsU610AnimatedArtCatalog : ScriptableObject
    {
        [Serializable]
        public sealed class FormAnimation
        {
            public string Form;
            public Sprite StaticSource;
            public Sprite[] Frames;
            public float[] Durations;
        }

        public List<FormAnimation> Forms = new List<FormAnimation>();
        private static MonsterTacticsU610AnimatedArtCatalog instance;

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void ResetCache() { instance = null; }

        public static bool TryGet(string form, Sprite source, out FormAnimation animation)
        {
            animation = null;
            if (string.IsNullOrEmpty(form) || source == null) return false;
            if (instance == null)
                instance = Resources.Load<MonsterTacticsU610AnimatedArtCatalog>("MonsterTacticsU610AnimatedArtCatalog");
            if (instance == null || instance.Forms == null) return false;
            foreach (FormAnimation entry in instance.Forms)
            {
                if (entry == null || !string.Equals(entry.Form, form, StringComparison.OrdinalIgnoreCase)
                    || entry.StaticSource != source || entry.Frames == null || entry.Frames.Length < 2)
                    continue;
                if (entry.Frames[0] == null) continue;
                animation = entry;
                return true;
            }
            return false;
        }
    }
}
